     *
     * @param date the date
     * @return the fiscal year, e.g. 2027 for 2026-07-01 through 2027-06-30
     */
    public static int of(LocalDate date) {
        return date.getMonthValue() >= FIRST_MONTH.getValue() ? date.getYear() + 1 : date.getYear();
