package org.springframework.samples.petclinic.acceptance;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import org.junit.jupiter.api.Test;
import org.springframework.samples.petclinic.util.Soundex;

import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;

/** identity-key-v2: exact key value, soundex-based collisions, soft match and deleted owners. */
class IdentityKeyTest extends AcceptanceBase {

	@Test
	void identityKeyIsSha256OfTelephoneEmailAndSoundex() throws Exception {
		ObjectNode o = structuredOwner();
		String telephone = o.get("telephone").asText();
		o.put("email", "Mixed." + uniqueEmail());
		JsonNode r = fetchOwner(createOwnerOk(o));
		String expected = sha256hex("+61" + telephone.substring(1) + "|" + o.get("email").asText().toLowerCase()
				+ "|" + Soundex.of(o.get("lastName").asText()));
		assertEquals(expected, r.get("identityKey").asText());
	}

	@Test
	void similarSoundingLastNameWithSameTelephoneAndEmailIsDuplicate() throws Exception {
		ObjectNode a = structuredOwner();
		a.put("lastName", "Smith");
		a.put("email", uniqueEmail());
		createOwnerOk(a);
		ObjectNode b = a.deepCopy();
		b.put("lastName", "Smyth");
		createOwner(b).andExpect(status().isConflict());
	}

	@Test
	void sameLastNameAndPostcodeWithDifferentTelephoneIsSoftMatch() throws Exception {
		ObjectNode a = structuredOwner();
		int first = createOwnerOk(a);
		ObjectNode b = a.deepCopy();
		b.put("telephone", uniqueTelephone());
		b.put("addressLine1", seq() + " Other Street");
		JsonNode r = fetchOwner(extractId(createOwner(b).andExpect(status().isCreated())));
		assertTrue(r.get("possibleDuplicate").asBoolean());
		assertEquals(first, r.get("possibleDuplicateOf").asInt());
	}

	@Test
	void declaredHouseholdMemberIsNotSoftMatch() throws Exception {
		ObjectNode a = structuredOwner();
		createOwnerOk(a);
		ObjectNode b = a.deepCopy();
		b.put("telephone", uniqueTelephone());
		b.put("sharesHousehold", true);
		JsonNode r = fetchOwner(extractId(createOwner(b).andExpect(status().isCreated())));
		assertFalse(r.get("possibleDuplicate").asBoolean());
	}

	@Test
	void deletedOwnerIsIgnoredByDuplicateDetection() throws Exception {
		ObjectNode a = structuredOwner();
		a.put("email", uniqueEmail());
		deleteOwner(createOwnerOk(a));
		JsonNode r = fetchOwner(extractId(createOwner(a.deepCopy()).andExpect(status().isCreated())));
		assertFalse(r.get("possibleDuplicate").asBoolean());
	}

	@Test
	void emailBlocklistAppliesBeforeDuplicateDetection() throws Exception {
		ObjectNode a = structuredOwner();
		createOwnerOk(a);
		ObjectNode b = a.deepCopy();
		b.put("email", "someone@mailinator.com");
		createOwner(b).andExpect(status().isBadRequest());
	}
}
